import { DirectionEnum } from '06_shared/types/types';
const check = (fraction, floor) => {
    if (fraction == null || Number.isNaN(fraction)) {
        return { value: null, floor, passes: false };
    }
    const exact = fraction * 100;
    return {
        value: Math.floor(exact + 1e-9),
        floor,
        passes: exact + 1e-9 >= floor,
    };
};
export const signalFilterCheck = (signal, prefs) => {
    if (prefs.trade_accuracy_mode === 'legacy') {
        const accuracy = check(signal.signal_accuracy, prefs.minimal_accuracy);
        return { mode: 'legacy', accuracy, passes: accuracy.passes };
    }
    const isSell = signal.signal_direction_created === DirectionEnum.SELL;
    const move = check(signal.signal_move_relative, isSell ? prefs.minimal_move_sell_relative : prefs.minimal_move_buy_relative);
    const direction = check(signal.signal_direction_relative, isSell ? prefs.minimal_direction_sell_relative : prefs.minimal_direction_buy_relative);
    return { mode: 'relative', move, direction, passes: move.passes && direction.passes };
};
